`timescale 1ns/1ps
// Stimulus and expected components are independently generated by the runner.
module tb_multi_bbox_limits;
 parameter integer RUN_LIMIT=0;
 parameter integer MINIMUM=1;
 reg clk=0, rst_n=0, v=0, m=0;
 reg [15:0] x=0,y=0;
 always #5 clk=~clk;
 wire ov,ol; wire [15:0] x1,y1,x2,y2,cnt; wire [7:0] id;
 generate if (RUN_LIMIT==0) begin
 multi_bbox #(.MIN_CNT(MINIMUM)) dut(.clk(clk),.rst_n(rst_n),.in_valid(v),.in_x(x),.in_y(y),.in_mask(m),
 .o_valid(ov),.o_last(ol),.o_x1(x1),.o_y1(y1),.o_x2(x2),.o_y2(y2),.o_cnt(cnt),.o_id(id));
 end else begin
 multi_bbox #(.MIN_CNT(MINIMUM),.MAX_RUN(RUN_LIMIT)) dut(.clk(clk),.rst_n(rst_n),.in_valid(v),.in_x(x),.in_y(y),.in_mask(m),
 .o_valid(ov),.o_last(ol),.o_x1(x1),.o_y1(y1),.o_x2(x2),.o_y2(y2),.o_cnt(cnt),.o_id(id));
 end endgenerate
 integer f,r,xx,yy,mm;
 always @(posedge clk) begin
 #1;
 if(rst_n && ov) $display("BOX %0d %0d %0d %0d %0d %0d %0d",id,x1,y1,x2,y2,cnt,ol);
 if(rst_n && ov && $isunknown({id,x1,y1,x2,y2,cnt,ol})) $display("FAIL unknown output");
 end
 initial begin
 repeat(4) @(negedge clk); rst_n=1;
 f=$fopen("pixels.txt","r"); if(!f) $fatal(1,"FAIL missing pixels");
 while(!$feof(f)) begin
 r=$fscanf(f,"%d %d %d\n",xx,yy,mm);
 if(r==3) begin @(negedge clk); v=1;x=xx;y=yy;m=mm;end
 else if(!$feof(f)) $fatal(1,"FAIL malformed pixels");
 end
 // The final empty row has y>0; wrap to flush the complete tested frame.
 @(negedge clk);x=0;y=0;m=0;v=1;
 @(negedge clk);v=0;
 repeat(256) @(negedge clk);
 $display("VERIFY_DONE bbox");$finish;
 end
 initial begin #2000000;$fatal(1,"FAIL timeout bbox");end
endmodule
